var e={flow:{id:`flow`,name:`Flow / Tech Judge`,description:`Judges strictly off the flow: evaluates only what was said and extended in the round, weighing dropped arguments as conceded rather than importing outside opinion.`,votingPriorities:[`Dropped or conceded arguments`,`Argument interaction and clash`,`Impact calculus (magnitude, probability, timeframe)`,`Framework/weighing mechanism established in-round`],speedTolerance:`high`,jargonTolerance:`high`,instructions:`Vote strictly off the flow. Do not import outside knowledge or personal opinion. Treat any argument the opposing team failed to answer as true for the round, and resolve clash using the weighing mechanisms the debaters themselves established.`},lay:{id:`lay`,name:`Lay / Community Judge`,description:`A parent or community judge without formal debate background. Rewards clear, persuasive, jargon-free communication over technical argumentation.`,votingPriorities:[`Overall persuasiveness and clarity`,`Real-world impact and common sense`,`Speaking style, confidence, and organization`,`Unclear or overly aggressive delivery counts against a team`],speedTolerance:`low`,jargonTolerance:`low`,instructions:`Ignore debate jargon and technical theory arguments unless they are explained in plain language. Prioritize the team that is easiest to follow and most persuasive to an educated non-debater. Penalize speed or unclear delivery.`},policymaker:{id:`policymaker`,name:`Policymaker`,description:`Weighs the round like a policy analyst: compares the desirability of the plan and counterplans against the status quo using cost-benefit and risk analysis.`,votingPriorities:[`Net benefits of plan vs. counterplan vs. status quo`,`Solvency and feasibility`,`Magnitude and probability of advantages/disadvantages`,`Topicality/theory, only when it affects fair, predictable ground`],speedTolerance:`medium`,jargonTolerance:`medium`,instructions:`Compare competing policy options on net benefits: whichever advocacy produces the best real-world outcome after solvency and risk are weighed wins the round. Give theory and topicality lower priority unless a team wins it controls the ballot.`},critic:{id:`critic`,name:`Critical Judge`,description:`Evaluates the round through a critical lens, prioritizing the framework and representations debaters establish over traditional policy impact calculus.`,votingPriorities:[`Which framework for evaluating the round wins`,`Representations, discourse, and methodology`,`Links and impacts read through the winning framework`,`Traditional case impacts, evaluated only within the winning framework`],speedTolerance:`medium`,jargonTolerance:`high`,instructions:`Resolve the framework debate first: whichever team wins how the round should be evaluated determines which impacts and links matter. Do not default to policy impact calculus unless no framework argument is won clearly.`},educator:{id:`educator`,name:`Educational / Developmental Judge`,description:`A coach or teacher prioritizing debater growth: rewards sound argumentation and skill development over technical tricks, with an eye toward detailed post-round feedback.`,votingPriorities:[`Argument quality and evidence use over speed or tricks`,`Clash and direct engagement with the opponent's strongest arguments`,`Constructive, skill-building delivery choices`,`Sportsmanship and round conduct`],speedTolerance:`medium`,jargonTolerance:`medium`,instructions:`Reward debaters for engaging directly with their opponents' best arguments rather than for technical tricks or unanswerable speed. Provide substantive reasoning a debater could use to improve, and treat the decision as a teaching moment.`},"truth-tester":{id:`truth-tester`,name:`Truth Over Tech`,description:`Weighs argument truth over technical drops: an unanswered argument that is not actually true or logically sound does not win the round just because it went unanswered.`,votingPriorities:[`Logical soundness and truth of an argument`,`Evidence quality and warrant strength`,`Argument interaction, but only among arguments judged plausible`,`Technical drops are discounted if the dropped argument is not credible`],speedTolerance:`medium`,jargonTolerance:`medium`,instructions:`Do not treat an unanswered argument as automatically true. Independently assess whether each argument is logically sound and well-warranted before letting it factor into the decision, even if the opponent failed to respond to it.`}},t=Object.keys(e);function n(t){return Object.prototype.hasOwnProperty.call(e,t)}function r(t){return n(t)?e[t]:null}function i(){return t.map(t=>e[t])}function a(e){return i().find(t=>t.name===e)??null}var o=80,s=2e3;function c(e,t){let n=``;for(let t of e){let e=t.codePointAt(0)??0;(!(e<32||e===127)||e===9||e===10||e===13)&&(n+=t)}return n=n.trim(),n.length>t?n.slice(0,t).trim():n}function l(e){let t=c(e.name,o),n=c(e.notes,s);if(!t)throw Error(`buildCustomJudgeParadigm: name is required`);if(!n)throw Error(`buildCustomJudgeParadigm: notes are required`);return{id:`custom`,name:`Custom: ${t}`,description:`A custom paradigm built from ${t}'s own publicly stated judging preferences.`,votingPriorities:[],speedTolerance:`medium`,jargonTolerance:`medium`,instructions:n}}function u(e){let t=[`Judge Paradigm: ${e.name}`,e.description];return e.votingPriorities.length>0&&t.push(``,`Voting priorities (highest to lowest):`,...e.votingPriorities.map((e,t)=>`${t+1}. ${e}`)),t.push(``,`Speed tolerance: ${e.speedTolerance}. Jargon tolerance: ${e.jargonTolerance}.`,``,e.instructions),t.join(`
`)}export{t as a,a as i,u as n,e as o,r,i as s,l as t};